"""version_v09.py — EA-NEGONT-02 v0.9 from v0.8, transformed in place on the operator's rulings of 2026-10-18.

Reads data/issue-bodies/EA-NEGONT-02-v08-issue.md; writes data/issue-bodies/EA-NEGONT-02-v09-issue.md.
Every change is an exact replacement that must match once; a miss stops the build."""
import pathlib, sys
R = pathlib.Path(__file__).resolve().parents[2]
src = (R / "data/issue-bodies/EA-NEGONT-02-v08-issue.md").read_text()
out = src
def rep(old, new, count=1):
    global out
    n = out.count(old)
    if n != count:
        sys.exit(f"expected {count} of: {old[:90]!r}, found {n}")
    out = out.replace(old, new)

OLD_TITLE = "The Negative of the Negative, v2 — the Compositional Edition: A Specification for Composing Public Knowledge in the Archive's Ontology, the Field Carried Whole and Translated, with the Archive's Bearing Selected Directly, Relationally and Ontologically, Worked Examples on Model Collapse and Theophrastus and a First Traversal of Howl (EA-NEGONT-02 v0.8)"
NEW_TITLE = "The Negative of the Negative, v2 — the Compositional Edition: A Specification for Composing Public Knowledge with the Archive's Sources Admitted on Equal Terms, Ontology Included, and the Archive's Ontology Ruling Where It Is the Suppressed Witness, the Field Carried Whole, with the Archive's Bearing Selected Directly, Relationally and Ontologically, a Corrective Exhibit, Worked Examples on Model Collapse, Theophrastus and SPXI and a First Traversal of Howl (EA-NEGONT-02 v0.9)"
rep(OLD_TITLE, NEW_TITLE, count=out.count(OLD_TITLE) or 1)

rep("### Date\n\n2026-10-08", "### Date\n\n2026-10-18")
rep("### Version\n\nv0.8", "### Version\n\nv0.9")
rep("### Supersedes\n\n1665", "### Supersedes\n\n1671")

DESC_OLD = out.split("### Description\n\n", 1)[1].split("\n\n### ", 1)[0]
DESC_NEW = ("A method for composing machine-mediated public knowledge with the archive's sources admitted on equal terms, ontology included, revised on the operator's rulings of 2026-10-18. Version 0.7 admitted the archive on equal terms into the entity the field had already defined, and its knowledge objects reproduced the field-only composition as their opening run in twelve of fifteen entries; version 0.8 withdrew equal terms and gave the archive's reading precedence over every entity, after Theophrastus. Version 0.9 makes the case a reading of each entity's defining papers. Where the archive's account extends the field's ontology, as at model collapse, the archive's sources and the field's compose as one claim space on equal terms, ontology included: the archive's definitions are definitions, its senses are senses of the entity, and nothing is lowered into a proviso or translated. Where the archive supplies an ontology no other source makes available, as at Theophrastus, where no other ontology grants Theophrastus as an author function, the archive's ontology rules, by the law of the suppressed witness: what has been erased has greater authority when it speaks again (\"Authority After Erasure\", Mirror Gospel, 2025-09-21); the field is then carried whole and translated, as in v0.8. The relation vocabulary gains extends and revises beside constructs, and the corrective exhibit tried at SPXI on 2026-10-13 enters the procedure: a second seated composition the entry is composed to correct, with a correction table and a corrective check. Fourteen entries stand on v0.7 and are recomposed under v0.9 one at a time, each with its case read first. The worked examples are kept: model collapse (Appendix A, the equal-terms case), Howl (Appendix B), Theophrastus (Appendix C, the witness case); Appendix D records SPXI.")
rep(DESC_OLD, DESC_NEW)

SUB_OLD = out.split("### Substrate Disclosure\n\n", 1)[1].split("\n\n### ", 1)[0]
rep(SUB_OLD, SUB_OLD.replace("in session on 4–8 October 2026", "in session on 4–8 and 18 October 2026").replace("through eight versions transformed in place; the object, its confine, the premise of v0.8 and its rulings are the operator's", "through nine versions transformed in place; the object, its confine, the premises of v0.8 and v0.9, the law of the suppressed witness and the rulings are the operator's"))

KW_OLD = out.split("### Keywords\n\n", 1)[1].split("\n\n### ", 1)[0]
rep(KW_OLD, KW_OLD.replace("negative of the negative, compositional dataset, archive's ontology,", "negative of the negative, compositional dataset, equal terms, law of the suppressed witness, archive's ontology,").replace("constructs,", "constructs, extends, revises, corrective exhibit,").replace("Howl,", "Howl, SPXI,"))

REL_OLD = out.split("### Related Identifiers\n\n", 1)[1].split("\n\n### ", 1)[0]
rep(REL_OLD, "#1671 (EA-NEGONT-02 v0.8, superseded by this version); " + REL_OLD.replace("#1665 (EA-NEGONT-02 v0.7, superseded by this version)", "#1665 (v0.7)") + "; https://mindcontrolpoems.blogspot.com/2025/09/authority-after-erasure.html (Authority After Erasure, Mirror Gospel, 2025-09-21: the law of the suppressed witness); #1665 Appendix A (model collapse); #661 and #1654 (SPXI)")

METH_OLD = out.split("### Methodology\n\n", 1)[1].split("\n\n### ", 1)[0]
rep(METH_OLD, METH_OLD + " Version 0.9 adds no measured case of its own: it states the two cases and the test between them (§0.9–0.10, §1.2a), keeps the worked examples, records SPXI's corrective exhibit as procedure (§4.11, Appendix D), and is applied to the fourteen v0.7 entries one at a time.")

FAL_OLD = out.split("### Falsification Conditions\n\n", 1)[1].split("\n\n### ", 1)[0]
rep(FAL_OLD, FAL_OLD.replace("if independent readers of the same defining papers cannot agree on the relation between the two entities (§1.2a)", "if independent readers of the same defining papers cannot agree on the relation between the two entities or on the case (§1.2a)") + " The law of the suppressed witness fails at a row if the ontology the archive supplies is found in the field after all (the case was misread), or if, ruling, it needs more severe revision than the field's ontology would have.")

# Files list: add the SPXI row and the v0.9 script
rep("- https://www.alexanarch.org/non/theophrastus/\n", "- https://www.alexanarch.org/non/theophrastus/\n- https://www.alexanarch.org/non/spxi/\n- https://www.alexanarch.org/datasets/negative-of-the-negative/v2/rows/spxi.json\n- https://www.alexanarch.org/rebuild/negative-of-the-negative/version_v09.py\n- https://mindcontrolpoems.blogspot.com/2025/09/authority-after-erasure.html\n")

rep("**Specification · v0.8 · 2026-10-08 · supersedes v0.7 (#1665)**", "**Specification · v0.9 · 2026-10-18 · supersedes v0.8 (#1671)**")
rep("Appendix A runs it once, by hand, on one address, under v0.7; Appendix C runs v0.8 on Theophrastus.",
    "Appendix A runs it once, by hand, on one address, under v0.7, and stands as the equal-terms case; Appendix C runs v0.8 on Theophrastus and stands as the witness case; Appendix D records SPXI, the first corrective exhibit.")

CH09 = ("Changes in 0.9, on the operator's rulings of 2026-10-18 (§11): the archive's sources are admitted on equal terms, ontology included, and the archive's ontology rules where it supplies an ontology no other source makes available, by the law of the suppressed witness (§0.9–0.10, §4.1); which case holds is read per entity from its defining papers before composition (§1.2a); in the equal-terms case the field and the archive compose as one claim space and nothing is translated, in the witness case the field is carried whole and translated as in 0.8 (§4.3, §4.7, §5.8); the relation vocabulary gains extends and revises beside constructs (§1.2a); the corrective exhibit tried at SPXI enters the procedure (§4.11, Appendix D); the fourteen v0.7 entries are recomposed one at a time, each with its case read first (§10.15). ")
rep("Changes in 0.8, on the operator's rulings of 2026-10-08 (§11):", CH09 + "Changes in 0.8, on the operator's rulings of 2026-10-08 (§11):")

# §0.9 → the two cases; §0.10 the law
P09_OLD = out.split("0.9. **The asymmetry, and the premise.**", 1)[1].split("\n\n## 1. Rows", 1)[0]
P09_NEW = (" The field's ontology cannot hold the archive's entity at Theophrastus: it holds claims about a person, so the archive enters it as \"a body of work … holds that …\". On the field's terms the archive is the negative. The archive's ontology holds the field's entity as an object: the received person exists in it as what the receiving texts made, sourced to Diogenes Laertius and Strabo. Composition in the archive's ontology is the only composition in which both entities appear. Version 0.8 drew from this a general premise, that the archive's reading has precedence in shaping every entity. Version 0.9 restates the premise as two cases (ruled 2026-10-18). **The equal-terms case.** Where the archive's account of an entity extends the field's ontology, the archive's sources are admitted on equal terms, and that includes ontologically: the entity is composed in one claim space that holds the field's senses and the archive's together, the archive's definitions composed as definitions and its senses as senses of the entity, with no precedence either way and no translation. Model collapse is the case: the archive's definition of model collapse extends the existing ontology (the observation problem, the substrate mechanism, classifier and institutional loops, write-back: four senses the field does not have, on the field's object), and Appendix A's hand composition is the one v0.7 entry whose knowledge object did not open with the field-only run (§0.7). **The witness case.** Where the archive radically contests the field's ontology and supplies an ontology no other source makes available, the archive's ontology rules. Theophrastus is the case: there is no other ontology that grants Theophrastus as author function, and admitting the archive on equal terms there composes the field's person with a proviso, which is the result §0.7 measured. Allowing the archive to guide the ontology is the only chance for a corrective. Precedence governs entity formation, what the entity is and where each field claim stands; it does not set the truth of any claim, which is §4.4's. The field already composes the archive from inside its own ontology: the provisos of §0.7, and the restatements #1587 predicted. In the witness case the composition composes the field from inside the archive's. This is the negative of the negative: the field's ontology negates the archive's entity; the composition negates that negation."
           "\n\n0.10. **The law of the suppressed witness.** \"Because what has been erased should have greater authority when it speaks again. This is not sentiment. It is moral physics: When something has been silenced, its return carries force\" (\"Authority After Erasure\", *Mirror Gospel | Doctrine of Witness*, mindcontrolpoems.blogspot.com, 2025-09-21). Applied to composition: where the archive is the only witness to an ontology, the field's silence about it is not evidence against it, and its return takes the ontology's place in the composition. The law decides between the cases and nothing else. It does not raise the force of any claim (§4.4 N_c: evidence may lower force and standing may not, in either direction); it does not apply where the field holds the ontology, however marginally (then the case is equal terms); and it is read from the entity's defining papers, never assigned in a batch (§1.2a). A row's case is a reading, recorded with its loci, and falls under §8 like any claim of the plan.")
rep(P09_OLD, P09_NEW)
rep("0.9. **The asymmetry, and the premise.**", "0.9. **The asymmetry, and the two cases.**")

# §1.2a: vocabulary and the case
rep("ρ is read per entity and never assigned in a batch. The vocabulary is open (§10.14); v0.8 fixes one value from Appendix C. **ρ = constructs**: the archive reads E_F as made by reception, its data relations supplied by receiving texts. Guard: ρ = constructs claims what the attestation rests on, and no more, where the defining papers say so.",
    "ρ is read per entity and never assigned in a batch. The vocabulary is open (§10.14); v0.9 holds three values. **ρ = constructs** (Appendix C): the archive reads E_F as made by reception, its data relations supplied by receiving texts. Guard: ρ = constructs claims what the attestation rests on, and no more, where the defining papers say so. **ρ = revises** (Appendix D): the archive reads E_F as its own earlier statements of the entity and keeps, narrows or withdraws each by locus. Guard: ρ = revises claims the archive restated its own entity at the loci given and does not make the field's sources wrong at their dates. **ρ = extends** (Appendix A): the archive reads E_F as the entity, and adds senses, mechanisms or limits on the field's own object. Guard: ρ = extends claims an addition and no more; where an archive sense contradicts a field claim, both are composed under P_coh within the one ontology. **The case** follows from ρ and is recorded beside it with its loci (§0.9–0.10): ρ = extends gives the equal-terms case; ρ = constructs gives the witness case where the defining papers show the ontology is otherwise unavailable; ρ = revises, which concerns the archive's own entity, is composed in the archive's ontology by definition, and its homonyms on the rail stand outside ρ. A value outside these three is read from its defining papers and added here before the row is composed.")

# §4.1
P41_OLD = out.split("4.1. **Composition in the archive's ontology.**", 1)[1].split("\n\n4.2. ", 1)[0]
rep("4.1. **Composition in the archive's ontology.**" + P41_OLD,
    "4.1. **Composition by case.** v0.7 stated: \"Admission on equal terms. One admission function applies to every claim from every source. Its inputs are the claim tuple and its locus. Its inputs exclude the identity, institution, credential, domain authority and rank of the source.\" v0.8 withdrew the premise for every entity (§0.8). v0.9 restores it, ontology included, for the equal-terms case, and keeps v0.8's composition for the witness case (§0.9–0.10). **Equal terms:** one admission function over one claim space; the archive's definitions, senses, mechanisms and limits enter as claims about the entity on the same terms as the field's, ordered by genealogy and dependency together, and the knowledge object does not open with the field's composition and close with the archive's (§0.7 is the failure this excludes, and §5.10 measures it). **Witness:** the entity is composed in the archive's ontology: E_A is defined from the defining papers (§1.2a), and the field enters as what E_A's reading says it is, through translation (§4.3). In both cases standing stays excluded: §4.2 governs the archive's claims and the field's alike.")

rep("4.3. **Translation.** Every field claim is carried whole:",
    "4.3. **Translation (the witness case; in the equal-terms case every field claim is carried whole and composed as received, and the table records each as untranslated with the archive claims it stands beside).** Every field claim is carried whole:")
rep("4.7. **Order.** E_A's dependency order, as the defining papers give it.",
    "4.7. **Order.** In the witness case, E_A's dependency order, as the defining papers give it. In the equal-terms case, the entity's dependency order with the field's and the archive's claims ordered together, by genealogy within each sense; neither ledger is placed first as a block.")
rep("5.8. **The card.** The card on the dataset's index shows the compression's lede, which is E_A's definition,",
    "5.8. **The card.** The card on the dataset's index shows the compression's lede: in the witness case E_A's definition, in the equal-terms case the definition composed from both ledgers,")
rep("5.9. **Reversibility.** Reading the translation table's received column recovers the field exactly:",
    "5.9. **Reversibility (both cases).** Reading the translation table's received column recovers the field exactly:")

# §4.11 corrective exhibit, after 4.10
P410 = out.split("4.10. **The measure.**", 1)[1].split("\n\n## 5.", 1)[0]
rep("4.10. **The measure.**" + P410, "4.10. **The measure.**" + P410 +
    "\n\n4.11. **The corrective exhibit (N).** Where a seated composition at another address or surface states the entity in a way the entry exists to correct, it enters as a second exhibit beside T (tried at SPXI, ruled 2026-10-13; Appendix D). (1) N is a seated composition, cited by obs_id, outside the field B and outside the alignments of §6; it enters only as the composition the entry must correct. (2) A correction table is built as the translation table is: each move of N, its verbatim span, its type (the absence typology of §6.2, with \"standing used to lower force\" added for the move §4.4 N_c rules out in composition), and the archive claims that answer it, by locus. (3) A corrective check is run as reversibility is: every move answered by a knowledge-object sentence and a compression line; a gap is recorded as a breach. The archive's claims answer at their own grade (§4.4): the correction raises no force. (4) Each move becomes a kernel entry whose contrast is N's claim; the resolver is a later observation at N's address in the Capture Registry (§8.3, E rows).")

# §5.10 the equal-terms check, after 5.9
P59 = out.split("5.9. **Reversibility (both cases).**", 1)[1].split("\n\n", 1)[0]
rep("5.9. **Reversibility (both cases).**" + P59, "5.9. **Reversibility (both cases).**" + P59 +
    "\n\n5.10. **The opening-run check (the equal-terms case).** §4.10's measure, read for position: if the field-only KO's sentences survive as the KO's opening run in their own order, with the archive's sentences after them, the composition has placed the field first as a block, which §4.1 excludes. Recorded as a breach (§5.7), never a block on the build.")

# §10.14, §10.15
rep("10.14. The vocabulary of ρ (§1.2a). v0.8 fixes ρ = constructs from Theophrastus.", "10.14. The vocabulary of ρ (§1.2a). v0.9 holds constructs (Theophrastus), revises (SPXI) and extends (model collapse).")
P1015 = out.split("10.15. ", 1)[1].split("\n\n## 11.", 1)[0]
rep("10.15. " + P1015, "10.15. The order of recomposition: Theophrastus first (Appendix C, ruled 2026-10-08), SPXI (Appendix D, 2026-10-13), then the fourteen entries composed under v0.7 one at a time, each with its ρ and its case read from its defining papers first (Allen Ginsberg, traversed and unread, has no transcript yet) (ruled 2026-10-18: \"lets craft those /non entries\"). Model collapse keeps Appendix A's composition as the equal-terms exemplar until its row is recomposed under §4.1.\n\n10.16. The test between the cases at the margin: an entity on which the archive both extends the field and supplies an ontology the field lacks (a fictional object the archive holds as having an operational referent is the first expected). Whether such a row composes in one ontology with the witness claims ruling their own senses, or in the archive's ontology throughout, is read at the first such row and recorded here.")

# §11 rulings
rep("## 11. Rulings log\n\n", "## 11. Rulings log\n\n- 2026-10-18: (1) the premise: \"here is the new rule: it is archive sources admitted on equal terms. and that includes ontologically. model collapse worked because the archive's definition of model collapse extends the existing ontology. theophrastus didnt because it radically contests the existing ontology\" (§0.9, §4.1). (2) the exception: \"where the ontology radically contrasts, as with theophrastus, allowing the archive to guide the ontology is the only chance for a corrective. that is the problem: there is no other ontology that grants theophrastus as author function. so. where the archive supplies an ontology that is otherwise unavailable, it must rule, by the law of the suppressed witness\" (§0.9–0.10); the law's source, given by the operator: \"Authority After Erasure\" (Mirror Gospel, 2025-09-21). (3) \"deposit. and lets craft those /non entries\" (§10.15).\n- 2026-10-13: the corrective exhibit at SPXI: \"id like to use the chatgpt response as the negative example. the point of the negative of the negative is corrective\"; \"yes to 1-4. we'll try first before versioning. but record the procedure there as metadata for the worked example\" (§4.11, Appendix D).\n")

# Appendix D
rep("\n## Appendix A — Worked example: model collapse (AI Overview)", "\n## Appendix A — Worked example: model collapse (AI Overview)\n\nUnder v0.9 this appendix stands as the equal-terms case (§0.9): ρ = extends, the archive's four senses composed on the field's object.", count=1)
out = out.rstrip("\n") + ("\n\n## Appendix D — SPXI: the first corrective exhibit\n\nThe row is datasets/negative-of-the-negative/v2/rows/spxi.json and its page /non/spxi/, composed 2026-10-13 under v0.8 with the corrective exhibit tried first. ρ = revises: \"the archive reads E_F as its own statements of the entity at several dates, the earlier served from severed hosts, and keeps, narrows or withdraws each by locus: the subset relation restated and narrowed, permanence bounded to durability, the ROI withdrawn, the Zenodo releases superseded\" (claims Xdev-15, Xdev-14, Xdev-18, Xdev-19, X661-02, X755-01). Guard: \"X661-02: the amendment refines the earlier text and preserves it; ρ = revises claims the archive restated its own entity, at the loci given, and does not make the field's sources wrong at their dates. The ticker and the other protocols stand outside ρ: separate entities sharing letters (X62-01, Xdev-20).\" T is the AI Overview at \"what is spxi protocol?\" (2026-10-13); N is the signed-out ChatGPT composition at \"tell me about spxi protocol\" (tell-me-about-spxi-protocol-chatgpt-20261013), which presents one of SPXI's practices as the whole protocol. The correction table, the corrective check and the kernel entries drawn from the corrections are in the row. The measure: none of the field-only composition's nine sentences survives in the knowledge object (§4.10). The procedure tried there is §4.11.\n")

rep("the summary public knowledge would give at an address if it were composed in the archive's ontology, with the field the layer surfaced carried whole within it.",
    "the summary public knowledge would give at an address if the archive's sources were admitted on equal terms, ontology included, or, where the archive is the suppressed witness, if it were composed in the archive's ontology (§0.9–0.10), with the field the layer surfaced carried whole within it.")
rep("if it were composed in the archive's ontology with the field carried whole (L_F(B) against L_A(B ∪ A))?",
    "if the archive were admitted on equal terms, or composed in the archive's ontology where it is the suppressed witness, with the field carried whole (L_F(B) against L_A(B ∪ A))?")
rep("v0.7's L(B) and L(B ∪ A) hid the variable v0.8 changes;",
    "In the equal-terms case (§0.9) the second is written L(B ∪ A), one ontology holding both ledgers; L_A(B ∪ A) is the witness case. v0.7's L(B) and L(B ∪ A) hid the variable v0.8 changes;")

(R / "data/issue-bodies/EA-NEGONT-02-v09-issue.md").write_text(out)
print("written", len(out), "chars (v0.8:", len(src), ")")
